/*
 * GENERATED by scripts/build-tokens.mjs — edit tokens/*.json instead.
 *
 * The token layer every component resolves against. One stylesheet holds
 * both appearances; there is no JavaScript theme object and no build step
 * on the consumer's side.
 */

/* Appearance-independent tokens live on :root ALONE, never on `.light`. A
   nested light scope re-matches every `.light` rule, so anything declared
   there would reset back to its default instead of inheriting the value an
   outer Theme set. */
:root {
  --radius: 0.375rem;
  --radius-factor: 1;
  --radius-full: 0px;
  --radius-pill: 9999px;
  --font-weight-label: 653;
  --cursor-button: default;
  --cursor-link: pointer;
  --cursor-disabled: not-allowed;
  --font-sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';
  --font-mono: ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace;

  --duration-fast: 100ms;
  --duration-base: 150ms;
  --duration-slow: 200ms;
  --duration-spin: 800ms;
  --duration-spin-reduced: 2.5s;
  --focus-width: 2px;
  --focus-offset: 2px;
  --focus-offset-inset: -2px;
  --border-width: 1px;
  --border-width-selected: 2px;
  --layer-sticky: 10;
  --layer-overlay: 50;
  --layer-tooltip: 60;
  --layer-toast: 70;
  --target-coarse: 44px;

  /* Defaults: blue accent, gray gray. Overridden by
     [data-accent] / [data-gray] below, which the Theme component sets. */
  --accent-solid-light: oklch(54.6% 0.245 262.881);
  --accent-contrast-light: oklch(98.5% 0 0);
  --accent-ring-light: oklch(48.8% 0.243 264.376);
