   and inherits as a finished value, so setting --accent-solid-* further down
   the tree cannot reach a --color-background-brand-bold already computed at :root. Every element
   that changes the palette therefore has to restate the mapping, for the
   appearance it is in. */
[data-accent] {
  --color-background-brand-bold: var(--use-light, var(--accent-solid-light)) var(--use-dark, var(--accent-solid-dark));
  --color-text-brand-inverse: var(--use-light, var(--accent-contrast-light)) var(--use-dark, var(--accent-contrast-dark));
  --color-border-focused: var(--use-light, var(--accent-ring-light)) var(--use-dark, var(--accent-ring-dark));
  --color-text-brand: var(--use-light, var(--accent-text-light)) var(--use-dark, var(--accent-text-dark));
  --color-icon-brand: var(--use-light, var(--accent-text-light)) var(--use-dark, var(--accent-text-dark));
  --color-background-brand-subtlest: var(--use-light, var(--accent-subtle-light)) var(--use-dark, var(--accent-subtle-dark));
  --color-text-brand-bold: var(--use-light, var(--accent-subtle-text-light)) var(--use-dark, var(--accent-subtle-text-dark));
}

[data-gray] {
  --color-surface: var(--use-light, var(--gray-50)) var(--use-dark, var(--gray-950));
  --color-surface-raised: var(--use-light, oklch(100% 0 0)) var(--use-dark, var(--gray-900));
  --color-surface-overlay: var(--use-light, oklch(100% 0 0)) var(--use-dark, var(--gray-900));
  --color-text: var(--use-light, var(--gray-950)) var(--use-dark, var(--gray-50));
  --color-text-subtlest: var(--use-light, var(--gray-500)) var(--use-dark, var(--gray-400));
  --color-text-subtle: var(--use-light, var(--gray-600)) var(--use-dark, var(--gray-300));
  --color-text-inverse: var(--use-light, var(--gray-50)) var(--use-dark, var(--gray-50));
  --color-icon: var(--use-light, var(--gray-950)) var(--use-dark, var(--gray-50));
  --color-icon-subtle: var(--use-light, var(--gray-500)) var(--use-dark, var(--gray-400));
  --color-icon-inverse: var(--use-light, var(--gray-50)) var(--use-dark, var(--gray-50));
  --color-border: var(--use-light, var(--gray-200)) var(--use-dark, oklch(100% 0 0 / 10%));
  --color-border-input: var(--use-light, var(--gray-300)) var(--use-dark, oklch(100% 0 0 / 18%));
  --color-border-bold: var(--use-light, var(--gray-500)) var(--use-dark, var(--gray-400));
  --color-background-neutral: var(--use-light, var(--gray-100)) var(--use-dark, var(--gray-800));
  --color-background-input: var(--use-light, var(--gray-50)) var(--use-dark, var(--gray-800));
  --color-background-selected: var(--use-light, var(--gray-200)) var(--use-dark, oklch(100% 0 0 / 10%));
  --color-background-neutral-bold: var(--use-light, var(--gray-600)) var(--use-dark, var(--gray-600));
}

/* Derived tokens are declared on `*`, not `:root`, and that is load-bearing
   for the same reason as above: on :root they would freeze at the document
   root, so a Theme that sets --radius-factor further down would
   change nothing. On `*` every element recomputes them from what it
   inherits, which is what makes scoping work. */
* {
  /* Radius steps — the base scale multiplied by the preset's factor. */
  --radius-xs: calc(var(--radius) / 3 * var(--radius-factor));
  --radius-sm: calc(var(--radius) * 2 / 3 * var(--radius-factor));
  --radius-md: calc(var(--radius) * var(--radius-factor));
  --radius-lg: calc(var(--radius) * 4 / 3 * var(--radius-factor));
  --radius-xl: calc(var(--radius) * 2 * var(--radius-factor));
  --radius-2xl: calc(var(--radius) * 8 / 3 * var(--radius-factor));

  /* Radius intent — what components actually use.

     --radius-full is 0 except under radius="full-rounded", where it is 9999px. So
     max(step, --radius-full) resolves to the step normally and to a pill at
     full — that is --radius-control.

     Fields and panels take the same shape with a ceiling wrapped around it:
     min(cap, --radius-full) is 0 normally and the cap at full, so they step
     up with the preset without ever reaching a pill. A fully round text
     field reads as a search pill in a form that is not one, and a fully
     round card stops looking like a container. */
  --radius-control: max(var(--radius-md), var(--radius-full));
  --radius-field: max(var(--radius-md), min(var(--radius-lg), var(--radius-full)));
  --radius-panel: max(
    var(--radius-xl),
    min(var(--radius-2xl), var(--radius-full))
  );

  /* Radius by size tier. The tier picks the step (xs and sm the small one,
     md the default) and the intent picks what happens at radius="full-rounded": a
     control (Button, Tag, a tab) becomes a pill, a field stops one step up
     for the same reason --radius-field does. */
  --control-xs-radius: max(var(--radius-sm), var(--radius-full));
  --control-xs-radius-field: max(var(--radius-sm), min(var(--radius-md), var(--radius-full)));
  --control-sm-radius: max(var(--radius-sm), var(--radius-full));
  --control-sm-radius-field: max(var(--radius-sm), min(var(--radius-md), var(--radius-full)));
  --control-md-radius: max(var(--radius-md), var(--radius-full));
  --control-md-radius-field: max(var(--radius-md), min(var(--radius-lg), var(--radius-full)));

  /* Font roles, read from whichever faces the scope sets. */
  --font-heading: var(--font-sans);
  --font-prose: var(--font-sans);

  /* Spacing — the numeric steps and the six roles. */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-0-5: 0.125rem;
  --space-1-5: 0.375rem;
  --space-2-5: 0.625rem;
  --space-stack: 0.25rem;
  --space-inline: 0.5rem;
  --space-cluster: 0.75rem;
  --space-group: 1rem;
  --space-container: 1.5rem;
  --space-section: 1.5rem;

  /* The box ramp — every fixed height and square stands on one of these. */
  --box-2xs: 1rem;
  --box-xs: 1.25rem;
  --box-sm: 1.5rem;
  --box-md: 2rem;
  --box-lg: 2.5rem;
  --box-xl: 3rem;

  /* Control heights — one scale for every button, field, tab and menu row. */
  --control-xs: var(--box-xs);
  --control-sm: var(--box-sm);
  --control-md: var(--box-md);
  --control-lg: var(--box-lg);
  --control-xs-pad: 0.375rem;
  --control-sm-pad: 0.5rem;
  --control-md-pad: 0.625rem;
  --control-xs-pad-spacious: 0.375rem;
  --control-sm-pad-spacious: 0.75rem;
  --control-md-pad-spacious: 0.75rem;
  --control-xs-gap: 0.25rem;
  --control-sm-gap: 0.375rem;
  --control-md-gap: 0.375rem;

  /* Row height and component sizes. */
  --row-height: 3rem;
  --choice-box: 1rem;
  --radio-dot-size: 0.375rem;
  --switch-sm-w: 2rem;
  --switch-sm-h: 1rem;
  --switch-md-w: 2rem;
  --switch-md-h: 1rem;
  --switch-lg-w: 2.5rem;
  --switch-lg-h: 1.25rem;
  --progress-sm: 0.25rem;
  --progress-md: 0.5rem;
  --progress-lg: 0.75rem;
  --avatar-xs: 1rem;
  --avatar-sm: 1.5rem;
  --avatar-md: 2rem;
  --avatar-lg: 2.5rem;
  --avatar-xl: 6rem;
  --avatar-2xl: 8rem;
  --badge-sm: 1rem;
  --badge-md: 1rem;
  --badge-dot-sm: 0.375rem;
  --badge-dot-md: 0.5rem;

  /* Icon sizes — one per control tier. */
  --icon-xs: 0.75rem;
  --icon-sm: 0.875rem;
  --icon-md: 1rem;
  --icon-lg: 1.25rem;

  /* Type roles. Leading is a ratio of the size of the same name. */
  --text-heading-2xl: 2rem;
  --text-heading-xl: 1.75rem;
  --text-heading-lg: 1.5rem;
  --text-heading-md: 1.25rem;
  --text-heading-sm: 1rem;
  --text-heading-xs: 0.875rem;
  --text-heading-2xs: 0.75rem;
  --text-body-lg: 1rem;
  --text-body: 0.875rem;
  --text-body-sm: 0.75rem;
  --text-body-xs: 0.75rem;

  --leading-heading-2xl: calc(36 / 32);
  --leading-heading-xl: calc(32 / 28);
  --leading-heading-lg: calc(28 / 24);
  --leading-heading-md: calc(24 / 20);
  --leading-heading-sm: calc(20 / 16);
  --leading-heading-xs: calc(20 / 14);
  --leading-heading-2xs: calc(16 / 12);
  --leading-body-lg: calc(24 / 16);
  --leading-body: calc(20 / 14);
  --leading-body-sm: calc(16 / 12);
  --leading-body-xs: calc(16 / 12);

  /* Shadows read from the elevation tokens each appearance sets. */
  --shadow-none: var(--elevation-none);
  --shadow-raised: var(--elevation-raised);
  --shadow-overlay: var(--elevation-overlay);
  --shadow-2xs: var(--elevation-2xs);
  --shadow-xs: var(--elevation-xs);
  --shadow-sm: var(--elevation-sm);
  --shadow-md: var(--elevation-md);
  --shadow-lg: var(--elevation-lg);
  --shadow-xl: var(--elevation-xl);
  --shadow-2xl: var(--elevation-2xl);
}
